@router.get("/{review_id}", response_model=ReviewDetailOut)
def get_review(review_id: int, db: Session = Depends(get_db), current_user: User = Depends(get_current_user)):
    review = db.query(Review).filter(Review.id == review_id).first()
    if not review:
        raise HTTPException(status_code=404, detail="Review not found")
    return _enrich_review_detail(db, review)

@router.get("/{file_id}", response_model=FileRecordOut)
def get_file(file_id: int, db: Session = Depends(get_db), current_user = Depends(get_current_user)):
    file_record = db.query(FileRecord).filter(FileRecord.id == file_id).first()
    if not file_record:
        raise HTTPException(status_code=404, detail="File not found")
    return file_record

